      AgentStartEvent() => const <String, dynamic>{},
      AgentSettledEvent() => const <String, dynamic>{},
      TurnStartEvent() => const <String, dynamic>{},
      AgentEndEvent(:final messages) => {
        'messages': [
          for (final message in messages) _messageFrameJson(message),
        ],

