test('unknown_event passthrough frames are emittable', () => {
  assert.deepEqual(encodeUnknownEvent('future_widget', { size: 3 }), {
    v: 1,
    kind: 'unknown_event',
    originalKind: 'future_widget',
    payload: { size: 3 },
  });
});

